commit message:
Change verbosity level names SILENT, NORMAL, NERD, ANAL to PRINT_*, and
ERROR to PRINT_ALWAYS.  Mostly using the following script (call it fix_verbosity):
#!/usr/bin/perl -w

my $VERBOSITY_ERROR_RE="ERROR";
my $VERBOSITY_RE="(?:SILENT|NORMAL|VERBOSE|NERD|ANAL)";

foreach my $file (@ARGV) {
  warn "$file\n";
  open FP, "<$file";
  open FPO, ">$file.verbosity_fix";
  foreach my $line (<FP>) {
    if ($file =~ /System.f95/) {
      $line =~ s/((optional_default.*\(|call.*\(|case\s*\(|[,=<>]|::|\.(?:eq|lt|gt|le|ge)\.)\s*(verbosity\s*=)?\s*)\b$VERBOSITY_ERROR_RE\b/${1}PRINT_ALWAYS/ig;
      $line =~ s/((?:optional_default.*\(|call.*\(|case\s*\(|[,=<>]|::|\.(?:eq|lt|gt|le|ge)\.)\s*(?:verbosity\s*=)?\s*)\b($VERBOSITY_RE)\b/${1}PRINT_${2}/ig;
    } else {
      $line =~ s/((optional_default.*\(|call.*\(|case\s*\(|[,=<>]|\.(?:eq|lt|gt|le|ge)\.)\s*(verbosity\s*=)?\s*)\b$VERBOSITY_ERROR_RE\b/${1}PRINT_ALWAYS/ig;
      $line =~ s/((?:optional_default.*\(|call.*\(|case\s*\(|[,=<>]|\.(?:eq|lt|gt|le|ge)\.)\s*(?:verbosity\s*=)?\s*)\b($VERBOSITY_RE)\b/${1}PRINT_${2}/ig;
    }
    print FPO $line;
    # print $line;
  }
  close FP;
  close FPO;
}
# END OF SCRIPT

./fix_verbosity `find . -name '*.f95' -print`
for f in `find . -name '*.f95.verbosity_fix' -print`; do mv $f ${f/.verbosity_fix//}; done
cd Tools/quippy
./fix_verbosity `find tests -name '*.py' -print`
for f in `find tests -name '*.py.verbosity_fix' -print`; do mv $f ${f/.verbosity_fix//}; done

